using CodEat.Web;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using System.Net;
using System.Text.RegularExpressions;
using Xunit;
namespace CodEat.Tests;
public class AppFactory:WebApplicationFactory<Program>{
 readonly string path=Path.Combine(Path.GetTempPath(),"codeat-"+Guid.NewGuid()+".db");
 protected override void ConfigureWebHost(IWebHostBuilder builder){builder.UseEnvironment("Development");builder.ConfigureAppConfiguration((_,c)=>c.AddInMemoryCollection(new Dictionary<string,string?>{{"Demo:Sqlite","true"},{"ConnectionStrings:Demo","Data Source="+path},{"BookStack:Simulated","true"}}));}
 public async Task Initialize(){using var scope=Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();await db.Database.EnsureCreatedAsync();db.Settings.Add(new());var a=new Household{Name="A"};var b=new Household{Name="B"};db.Households.AddRange(a,b);await db.SaveChangesAsync();var roles=scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();await roles.CreateAsync(new("Admin"));var users=scope.ServiceProvider.GetRequiredService<UserManager<AppUser>>();foreach(var (email,h,admin) in new[]{("admin@example.test",a,true),("member@example.test",a,false),("other@example.test",b,false)}){var u=new AppUser{UserName=email,Email=email,HouseholdId=h.Id,MemberSlot=email=="member@example.test"?2:1,EmailConfirmed=true};Assert.True((await users.CreateAsync(u,"Test!Password123")).Succeeded);if(admin)await users.AddToRoleAsync(u,"Admin");}await Setup.Demo(scope.ServiceProvider);}
 public HttpClient Client()=>CreateClient(new(){AllowAutoRedirect=false,BaseAddress=new Uri("https://localhost")});
 public static string Token(string html)=>WebUtility.HtmlDecode(Regex.Match(html,"name=\"__RequestVerificationToken\" type=\"hidden\" value=\"([^\"]+)\"").Groups[1].Value);
 public static string Revision(string html)=>Regex.Match(html,"name=\"revision\" value=\"([^\"]+)\"").Groups[1].Value;
 public static async Task Login(HttpClient c,string email){var html=await c.GetStringAsync("/Account/Login");var result=await c.PostAsync("/Account/Login",new FormUrlEncodedContent(new Dictionary<string,string>{{"__RequestVerificationToken",Token(html)},{"Email",email},{"Password","Test!Password123"}}));Assert.Equal(HttpStatusCode.Redirect,result.StatusCode);}
}
public partial class IntegrationTests {
 [Fact] public async Task AccessIsolationFinalizationAndRealPdfs(){await using var app=new AppFactory();await app.Initialize();using var anonymous=app.Client();foreach(var route in new[]{"/","/?Tab=shopping","/?handler=Pdf&id=1&kind=shopping","/Admin/Recipes"})Assert.Equal(HttpStatusCode.Redirect,(await anonymous.GetAsync(route)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await anonymous.GetAsync("/catalogue")).StatusCode);
 using var admin=app.Client();using var member=app.Client();using var other=app.Client();await AppFactory.Login(admin,"admin@example.test");await AppFactory.Login(member,"member@example.test");await AppFactory.Login(other,"other@example.test");
 var html=await admin.GetStringAsync("/");var memberHtml=await member.GetStringAsync("/");Assert.Equal(AppFactory.Revision(html),AppFactory.Revision(memberHtml));Assert.NotEqual(AppFactory.Revision(html),AppFactory.Revision(await other.GetStringAsync("/")));Assert.Equal(HttpStatusCode.Redirect,(await member.GetAsync("/Admin/Recipes")).StatusCode);
 var noCsrf=await admin.PostAsync("/",new FormUrlEncodedContent(new Dictionary<string,string>{{"action","finalize"}}));Assert.Equal(HttpStatusCode.BadRequest,noCsrf.StatusCode);
 var post=new Dictionary<string,string>{{"__RequestVerificationToken",AppFactory.Token(html)},{"revision",AppFactory.Revision(html)},{"action","finalize"},{"confirm","true"}};
 Assert.Equal(HttpStatusCode.Redirect,(await admin.PostAsync("/",new FormUrlEncodedContent(post))).StatusCode);
 Assert.Equal(HttpStatusCode.Conflict,(await member.PostAsync("/",new FormUrlEncodedContent(new Dictionary<string,string>(post){["__RequestVerificationToken"]=AppFactory.Token(memberHtml)}))).StatusCode);
 using var scope=app.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();var export=await db.Exports.SingleAsync();foreach(var kind in new[]{"shopping","meals"}){var route=$"/?handler=Pdf&id={export.Id}&kind={kind}";Assert.Equal(HttpStatusCode.NotFound,(await other.GetAsync(route)).StatusCode);var pdf=await member.GetAsync(route);Assert.Equal("application/pdf",pdf.Content.Headers.ContentType!.MediaType);using var doc=UglyToad.PdfPig.PdfDocument.Open(await pdf.Content.ReadAsByteArrayAsync());var text=string.Join(" ",doc.GetPages().Select(x=>x.Text));Assert.Contains("Cod & Eat",text);Assert.Contains(kind=="shopping"?"cabillaud":"Conservation",text);}
 Assert.Contains("no-store",(await member.GetAsync("/")).Headers.CacheControl!.ToString());
 }
 [Fact] public async Task ImportIsIdempotentPreservesEnrichmentAndFailureKeepsCatalog(){await using var app=new AppFactory();await app.Initialize();using var scope=app.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();var sync=scope.ServiceProvider.GetRequiredService<BookStackSync>();await sync.Run(default);var r=await db.Recipes.SingleAsync(x=>x.BookStackId==9001);r.Servings=7;r.Ingredients=[new("riz",42,"g","Sec")];await db.SaveChangesAsync();await sync.Run(default);Assert.Single(await db.Recipes.Where(x=>x.BookStackId==9001).ToListAsync());Assert.Equal(7,r.Servings);Assert.Equal("riz",r.Ingredients.Single().Canonical);
 var cfg=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"BookStack:BaseUrl","https://bookstack.invalid"},{"BookStack:BookId","1"},{"BookStack:TokenId","test-id"},{"BookStack:TokenSecret","test-secret"}}).Build();var fail=new BookStackSync(db,new BookStackClient(new HttpClient(new FailingHandler()),cfg));await Assert.ThrowsAsync<HttpRequestException>(()=>fail.Run(default));Assert.Equal(3,await db.Recipes.CountAsync());}
 class FailingHandler:HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken c)=>throw new HttpRequestException("offline");}
 [Fact] public async Task PublicCatalogContainsOnlyPublishedAndValidJsonLd(){await using var app=new AppFactory();await app.Initialize();using var scope=app.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();var settings=await db.Settings.SingleAsync();settings.PublicCatalog=true;await db.SaveChangesAsync();using var c=app.Client();var html=await c.GetStringAsync("/catalogue");Assert.Contains("Cabillaud",html);Assert.DoesNotContain("Lentilles",html);var r=await db.Recipes.SingleAsync(x=>x.Status=="Publiée");var page=await c.GetStringAsync($"/catalogue/{r.Id}/{r.Slug}");File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"public-debug.html"),page);var json=Regex.Match(WebUtility.HtmlDecode(page),"<script type=\"application/ld\\+json\">(.*?)</script>",RegexOptions.Singleline).Groups[1].Value;using var data=System.Text.Json.JsonDocument.Parse(json);Assert.Equal("Recipe",data.RootElement.GetProperty("@type").GetString());Assert.Equal(4,data.RootElement.GetProperty("recipeIngredient").GetArrayLength());Assert.DoesNotContain("BookStackId",page);r.Status="Brouillon";await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await c.GetAsync($"/catalogue/{r.Id}/{r.Slug}")).StatusCode);Assert.DoesNotContain($"/catalogue/{r.Id}/",await c.GetStringAsync("/sitemap.xml"));}
 [Fact] public async Task ReminderDatabaseConstraintPreventsDuplicates(){await using var app=new AppFactory();await app.Initialize();using var scope=app.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();var rule=await db.Rules.FirstAsync();var service=scope.ServiceProvider.GetRequiredService<HouseholdService>();await service.EnsureReminders(rule.HouseholdId,new(2026,12,1));await service.EnsureReminders(rule.HouseholdId,new(2026,12,2));Assert.Equal(1,await db.Reminders.CountAsync(x=>x.RuleId==rule.Id));db.Reminders.Add(new(){HouseholdId=rule.HouseholdId,RuleId=rule.Id,Period=Kitchen.Due(rule,new(2026,12,1)).Period});await Assert.ThrowsAsync<DbUpdateException>(()=>db.SaveChangesAsync());}
}



